import { RemovalPolicy, aws_secretsmanager as sm } from 'aws-cdk-lib';
import { Construct } from 'constructs';

export interface SecretsProps {
  destroyOnDelete: boolean;
}

/**
 * Secrets generated by Secrets Manager. No value is ever written into the template;
 * tasks read them at start through their execution role.
 */
export class Secrets extends Construct {
  /** JSON `{ username, password }` for PostgreSQL. */
  public readonly database: sm.Secret;
  /** Plain AUTH token for Redis. */
  public readonly redisAuthToken: sm.Secret;
  /** Plain signing key for the API's JWTs. */
  public readonly jwt: sm.Secret;

  constructor(scope: Construct, id: string, props: SecretsProps) {
    super(scope, id);
    const removalPolicy = props.destroyOnDelete ? RemovalPolicy.DESTROY : RemovalPolicy.RETAIN;

    this.database = new sm.Secret(this, 'Database', {
      description: 'PostgreSQL credentials',
      removalPolicy,
      generateSecretString: {
        secretStringTemplate: JSON.stringify({ username: 'app' }),
        generateStringKey: 'password',
        passwordLength: 32,
        excludePunctuation: true,
      },
    });

    // Redis AUTH tokens must be 16-128 printable characters without @, " or /.
    this.redisAuthToken = new sm.Secret(this, 'RedisAuthToken', {
      description: 'Redis AUTH token',
      removalPolicy,
      generateSecretString: { passwordLength: 48, excludePunctuation: true },
    });

    this.jwt = new sm.Secret(this, 'Jwt', {
      description: 'JWT signing key',
      removalPolicy,
      generateSecretString: { passwordLength: 64, excludePunctuation: true },
    });
  }
}
